using System;using System.Data;using System.Data.SqlClient;using System.Collections.Generic;using FindIt.Models;namespace FindIt.DAL { public class ClaimRepository { public bool Submit(int item, int user, string desc) { using (var c = DatabaseHelper.GetConnection()) using (var cmd = new SqlCommand("INSERT INTO Claims(ItemId,ClaimerId,ClaimDescription) SELECT @i,@u,@d WHERE EXISTS(SELECT 1 FROM Items WHERE ItemId=@i AND Status='Open' AND UserId<>@u) AND NOT EXISTS(SELECT 1 FROM Claims WHERE ItemId=@i AND ClaimerId=@u AND ClaimStatus<>'Rejected')", c)) { cmd.Parameters.AddWithValue("@i", item); cmd.Parameters.AddWithValue("@u", user); cmd.Parameters.AddWithValue("@d", desc); c.Open(); return cmd.ExecuteNonQuery() == 1; } } public List<Claim> Mine(int user) { var a = new List<Claim>(); using (var c = DatabaseHelper.GetConnection()) using (var cmd = new SqlCommand("SELECT c.ClaimId,c.ItemId,c.ClaimerId,c.ClaimDescription,c.ClaimStatus,c.AdminRemarks,c.CreatedAt,c.UpdatedAt,i.Title FROM Claims c JOIN Items i ON i.ItemId=c.ItemId WHERE ClaimerId=@u ORDER BY c.CreatedAt DESC", c)) { cmd.Parameters.AddWithValue("@u", user); c.Open(); using (var r = cmd.ExecuteReader()) while (r.Read()) a.Add(new Claim { ClaimId = r.GetInt32(0), ItemId = r.GetInt32(1), ClaimerId = r.GetInt32(2), ClaimDescription = r.GetString(3), ClaimStatus = r.GetString(4), AdminRemarks = r.IsDBNull(5) ? null : r.GetString(5), CreatedAt = r.GetDateTime(6), UpdatedAt = r.IsDBNull(7) ? (DateTime?)null : r.GetDateTime(7), ItemTitle = r.GetString(8) }); } return a; } public DataTable All() { using (var c = DatabaseHelper.GetConnection()) using (var da = new SqlDataAdapter("SELECT c.ClaimId,i.Title,c.ClaimDescription,c.ClaimStatus,c.AdminRemarks,c.CreatedAt,u.FullName AS Claimer,i.ItemId FROM Claims c JOIN Items i ON i.ItemId=c.ItemId JOIN Users u ON u.UserId=c.ClaimerId ORDER BY c.CreatedAt DESC", c)) { var t = new DataTable(); da.Fill(t); return t; } } public bool Decide(int id, bool approve, string remarks) { using (var c = DatabaseHelper.GetConnection()) { c.Open(); using (var tx = c.BeginTransaction()) { try { int item; using (var q = new SqlCommand("SELECT ItemId,ClaimStatus FROM Claims WITH (UPDLOCK,HOLDLOCK) WHERE ClaimId=@id", c, tx)) { q.Parameters.AddWithValue("@id", id); using (var r = q.ExecuteReader()) { if (!r.Read() || r.GetString(1) != "Pending") return false; item = r.GetInt32(0); } } if (approve) { using (var check = new SqlCommand("SELECT Status FROM Items WITH (UPDLOCK,HOLDLOCK) WHERE ItemId=@i", c, tx)) { check.Parameters.AddWithValue("@i", item); var status = check.ExecuteScalar(); if (status == null || Convert.ToString(status) != "Open") return false; } using (var reject = new SqlCommand("UPDATE Claims SET ClaimStatus='Rejected',AdminRemarks='Another claim approved',UpdatedAt=GETDATE() WHERE ItemId=@i AND ClaimId<>@id AND ClaimStatus='Pending';UPDATE Claims SET ClaimStatus='Approved',AdminRemarks=@r,UpdatedAt=GETDATE() WHERE ClaimId=@id;UPDATE Items SET Status='Claimed' WHERE ItemId=@i", c, tx)) { reject.Parameters.AddWithValue("@i", item); reject.Parameters.AddWithValue("@id", id); reject.Parameters.AddWithValue("@r", (object)remarks ?? DBNull.Value); reject.ExecuteNonQuery(); } } else using (var cmd = new SqlCommand("UPDATE Claims SET ClaimStatus='Rejected',AdminRemarks=@r,UpdatedAt=GETDATE() WHERE ClaimId=@id", c, tx)) { cmd.Parameters.AddWithValue("@r", (object)remarks ?? DBNull.Value); cmd.Parameters.AddWithValue("@id", id); cmd.ExecuteNonQuery(); } tx.Commit(); return true; } catch { tx.Rollback(); throw; } } } } } }